     9	/** Regras de dinheiro: centavos, arredondamento meio para o par e formato brasileiro. */
    10	public final class Dinheiro {
    11	
    12	    public static final BigDecimal ZERO = arredondar(BigDecimal.ZERO);
    13	
    14	    private Dinheiro() {
    15	    }
    16	
    17	    public static BigDecimal arredondar(BigDecimal valor) {
    18	        return valor.setScale(2, RoundingMode.HALF_EVEN);
    19	    }
    20	
    21	    public static BigDecimal valor(String texto) {
    22	        return arredondar(new BigDecimal(texto));
    23	    }
    24	
    25	    /** Aplica um percentual (ex.: 12 para 12%) ao valor e arredonda para centavos. */
    26	    public static BigDecimal percentual(BigDecimal valor, int percentual) {
    27	        return arredondar(valor.multiply(BigDecimal.valueOf(percentual)).divide(BigDecimal.valueOf(100)));
    28	    }
    29	
    30	    public static String formatar(BigDecimal valor) {
    31	        DecimalFormat formato = new DecimalFormat("#,##0.00", new DecimalFormatSymbols(new Locale("pt", "BR")));
    32	        formato.setRoundingMode(RoundingMode.HALF_EVEN);
    33	        return "R$ " + formato.format(valor);
