     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.temporal.ChronoUnit;
     6	
     7	/** Os dados de uma estadia que os planos de tarifa precisam para calcular e validar. */
     8	public record Estadia(Quarto quarto, LocalDate entrada, LocalDate saida, String codigoEmpresa) {
     9	
    10	    public int noites() {
    11	        return (int) ChronoUnit.DAYS.between(entrada, saida);
    12	    }
    13	
    14	    /** Soma das noites ao preço de tabela, com a alta temporada, arredondando noite a noite. */
    15	    public BigDecimal somaDasNoites() {
    16	        BigDecimal soma = Dinheiro.ZERO;
    17	        for (LocalDate noite = entrada; noite.isBefore(saida); noite = noite.plusDays(1)) {
    18	            soma = soma.add(precoDaNoite(noite));
    19	        }
    20	        return soma;
    21	    }
    22	
    23	    private BigDecimal precoDaNoite(LocalDate noite) {
    24	        if (Temporada.alta(noite)) {
    25	            return Dinheiro.percentual(quarto.diaria(), 120);
    26	        }
    27	        return quarto.diaria();
    28	    }
    29	}
