     3	import java.math.BigDecimal;
     4	
     5	/**
     6	 * Um plano de tarifa: sabe se a estadia pode usá-lo, como calcula o preço e quanto devolve no cancelamento.
     7	 * Um plano novo é uma subclasse nova, registrada em {@link PlanosDeTarifa}.
     8	 * Por padrão, o plano cobra as noites sem desconto e devolve tudo o que foi pago.
     9	 */
    10	public abstract class PlanoDeTarifa {
    11	
    12	    private final String codigo;
    13	
    14	    protected PlanoDeTarifa(String codigo) {
    15	        this.codigo = codigo;
    16	    }
    17	
    18	    public final String codigo() {
    19	        return codigo;
    20	    }
    21	
    22	    /** Lança {@link ApiException#invalida} quando a estadia não pode usar o plano. */
    23	    protected void validar(Estadia estadia) {
    24	    }
    25	
    26	    protected BigDecimal diarias(Estadia estadia) {
    27	        return estadia.somaDasNoites();
    28	    }
    29	
    30	    protected BigDecimal desconto(Estadia estadia, BigDecimal diarias) {
    31	        return Dinheiro.ZERO;
    32	    }
    33	
    34	    public BigDecimal devolucao(BigDecimal valorPago) {
    35	        return valorPago;
    36	    }
    37	
    38	    public final Cobranca cobrar(Estadia estadia) {
    39	        validar(estadia);
    40	        BigDecimal diarias = diarias(estadia);
    41	        return new Cobranca(diarias, desconto(estadia, diarias));
    42	    }
    43	}
