     9	
    10	    private static final List<PlanoDeTarifa> PLANOS = List.of(
    11	            new PlanoNormal(),
    12	            new PlanoNaoReembolsavel(),
    13	            new PlanoConvenio(),
    14	            new PlanoFimDeSemana(),
    15	            new PlanoEstadiaLonga());
