    20	    }
    21	
    22	    private static Map<String, PlanoDeTarifa> indexar() {
    23	        Map<String, PlanoDeTarifa> mapa = new LinkedHashMap<>();
    24	        PLANOS.forEach(plano -> mapa.put(plano.codigo(), plano));
    25	        return mapa;
    26	    }
