    15	public class ReservaServico {
    16	
    17	    private static final String ASSUNTO_CONFIRMACAO = "Reserva confirmada - Pousada Maré Alta";
    18	
    19	    private final Pousada pousada;
    20	    private final CaixaDeSaida caixaDeSaida;
    21	    private final List<Reserva> reservas = new ArrayList<>();
    22	
    23	    public ReservaServico(Pousada pousada, CaixaDeSaida caixaDeSaida) {
    24	        this.pousada = pousada;
    25	        this.caixaDeSaida = caixaDeSaida;
    26	    }
    27	
    28	    public synchronized Reserva criar(PedidoDeReserva pedido) {
    29	        if (!pedido.saida().isAfter(pedido.entrada())) {
    30	            throw ApiException.invalida("A saída deve ser depois da entrada");
    31	        }
    32	        if (pedido.hospedes() < 1) {
    33	            throw ApiException.invalida("É preciso pelo menos um hóspede");
    34	        }
    35	        Quarto quarto = pousada.quarto(pedido.numeroDoQuarto())
    36	                .orElseThrow(() -> new ApiException(Codigo.ROOM_NOT_FOUND, "Quarto não encontrado"));
    37	        var plano = PlanosDeTarifa.porCodigo(pedido.plano());
    38	        var estadia = new Estadia(quarto, pedido.entrada(), pedido.saida(), pedido.codigoEmpresa());
    39	        var hospede = new Hospede(pedido.nome(), pedido.email(), pedido.cpf());
    40	        Reserva reserva = new Reserva(reservas.size() + 1, hospede, estadia, pedido.hospedes(), plano);
    41	        if (pedido.hospedes() > quarto.capacidade()) {
    42	            throw new ApiException(Codigo.CAPACITY_EXCEEDED, "O quarto comporta até " + quarto.capacidade() + " pessoas");
    43	        }
    44	        boolean ocupado = reservas.stream()
    45	                .filter(r -> r.status() != StatusReserva.CANCELLED)
    46	                .anyMatch(r -> r.conflitaCom(quarto, pedido.entrada(), pedido.saida()));
    47	        if (ocupado) {
    48	            throw new ApiException(Codigo.ROOM_UNAVAILABLE, "Quarto já reservado em alguma das noites");
    49	        }
    50	        reservas.add(reserva);
    51	        return reserva;
    52	    }
    53	
    54	    public synchronized Reserva buscar(int id) {
    55	        if (id < 1 || id > reservas.size()) {
    56	            throw new ApiException(Codigo.RESERVATION_NOT_FOUND, "Reserva não encontrada");
    57	        }
    58	        return reservas.get(id - 1);
    59	    }
    60	
    61	    public synchronized List<Reserva> todas() {
    62	        return List.copyOf(reservas);
    63	    }
    64	
    65	    public synchronized Reserva confirmar(int id) {
    66	        Reserva reserva = buscar(id);
    67	        reserva.confirmar();
    68	        caixaDeSaida.enviarEmail(reserva.hospede().email(), ASSUNTO_CONFIRMACAO, textoDaConfirmacao(reserva));
    69	        return reserva;
    70	    }
    71	
    72	    public synchronized Reserva cancelar(int id) {
    73	        return alterar(id, Reserva::cancelar);
    74	    }
    75	
    76	    public synchronized Reserva fazerCheckIn(int id) {
    77	        return alterar(id, Reserva::fazerCheckIn);
    78	    }
    79	
    80	    public synchronized Comprovante fazerCheckOut(int id) {
    81	        return Comprovante.de(alterar(id, Reserva::fazerCheckOut));
    82	    }
    83	
    84	    public synchronized Comprovante segundaVia(int id) {
    85	        Reserva reserva = buscar(id);
    86	        if (!reserva.status().paga()) {
    87	            throw new ApiException(Codigo.OPERATION_NOT_ALLOWED, "A segunda via só existe para reserva paga");
    88	        }
    89	        return Comprovante.de(reserva);
    90	    }
    91	
    92	    private Reserva alterar(int id, Consumer<Reserva> operacao) {
    93	        Reserva reserva = buscar(id);
    94	        operacao.accept(reserva);
    95	        return reserva;
    96	    }
    97	
    98	    private static String textoDaConfirmacao(Reserva reserva) {
    99	        return "Olá, " + reserva.hospede().nome() + "!\n\n"
   100	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
   101	                + Comprovante.de(reserva).texto() + "\n\n"
   102	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   103	                + "Até breve!";
   104	    }
