    13	final class Pedidos {
    14	
    15	    private Pedidos() {
    16	    }
    17	
    18	    static PedidoDeReserva reserva(ObjectMapper json, String corpo) {
    19	        JsonNode raiz;
    20	        try {
    21	            raiz = json.readTree(corpo);
    22	        } catch (JsonProcessingException e) {
    23	            throw ApiException.invalida("O corpo não é um JSON válido");
    24	        }
    25	        if (raiz == null || !raiz.isObject()) {
    26	            throw ApiException.invalida("O corpo deve ser um objeto JSON");
    27	        }
    28	        return new PedidoDeReserva(
    29	                inteiro(raiz, "roomNumber"),
    30	                texto(raiz, "guestName"),
    31	                texto(raiz, "guestEmail"),
    32	                texto(raiz, "guestCpf"),
    33	                data(texto(raiz, "checkIn")),
    34	                data(texto(raiz, "checkOut")),
    35	                inteiro(raiz, "guests"),
    36	                texto(raiz, "ratePlan"),
    37	                textoOpcional(raiz, "companyCode"));
    38	    }
    39	
    40	    static LocalDate data(String texto) {
    41	        try {
    42	            return LocalDate.parse(texto);
    43	        } catch (DateTimeParseException | NullPointerException e) {
    44	            throw ApiException.invalida("Data fora do formato AAAA-MM-DD");
    45	        }
    46	    }
    47	
    48	    static YearMonth mes(String texto) {
    49	        try {
    50	            return YearMonth.parse(texto);
    51	        } catch (DateTimeParseException | NullPointerException e) {
    52	            throw ApiException.invalida("Mês fora do formato AAAA-MM");
    53	        }
    54	    }
    55	
    56	    private static String texto(JsonNode raiz, String campo) {
    57	        JsonNode valor = raiz.get(campo);
    58	        if (valor == null || !valor.isTextual() || valor.asText().isBlank()) {
    59	            throw ApiException.invalida("Campo obrigatório ausente ou inválido: " + campo);
    60	        }
    61	        return valor.asText();
    62	    }
    63	
    64	    private static String textoOpcional(JsonNode raiz, String campo) {
    65	        JsonNode valor = raiz.get(campo);
    66	        return valor != null && valor.isTextual() ? valor.asText() : null;
    67	    }
    68	
    69	    private static int inteiro(JsonNode raiz, String campo) {
    70	        JsonNode valor = raiz.get(campo);
    71	        if (valor == null || !valor.isInt()) {
    72	            throw ApiException.invalida("Campo obrigatório ausente ou inválido: " + campo);
    73	        }
    74	        return valor.asInt();
    75	    }
    76	}
