    22	    public Javalin criar() {
    23	        Javalin app = Javalin.create();
    24	
    25	        app.get("/rooms", ctx -> responder(ctx, 200, pousada.quartos().stream().map(Respostas::de).toList()));
    26	        app.post("/reservations", ctx -> responder(ctx, 201,
    27	                Respostas.de(reservas.criar(Pedidos.reserva(json, ctx.body())))));
    28	        app.get("/reservations/{id}", ctx -> responder(ctx, 200, Respostas.de(reservas.buscar(id(ctx)))));
    29	        app.post("/reservations/{id}/confirmation", ctx -> responder(ctx, 200, Respostas.de(reservas.confirmar(id(ctx)))));
    30	        app.post("/reservations/{id}/cancellation", ctx -> responder(ctx, 200, Respostas.de(reservas.cancelar(id(ctx)))));
    31	        app.post("/reservations/{id}/check-in", ctx -> responder(ctx, 200, Respostas.de(reservas.fazerCheckIn(id(ctx)))));
    32	        app.post("/reservations/{id}/check-out", ctx -> responder(ctx, 200, Respostas.de(reservas.fazerCheckOut(id(ctx)))));
    33	        app.get("/reservations/{id}/document", ctx -> responder(ctx, 200, Respostas.de(reservas.segundaVia(id(ctx)))));
